package bin.nt.dex2c.writer;

import java.util.*;
import com.android.tools.smali.dexlib2.iface.Method;
import com.android.tools.smali.dexlib2.iface.reference.*;
import bin.nt.dex2c.basic_blocks.*;import bin.nt.dex2c.compiler.*;import bin.nt.dex2c.graph.*;import bin.nt.dex2c.instruction.*;import bin.nt.dex2c.util.Types;

/** Native writer. It deliberately emits ordinary JNI instead of relying on an Android runtime library. */
public final class CppWriter{
 public String write(IrMethod ir,boolean dynamic){StringBuilder b=new StringBuilder();Method m=ir.method;String jni=JniNames.name(m);b.append("\n/* ").append(m.getDefiningClass()).append("->").append(m.getName()).append(descriptor(m)).append(" */\n");
  b.append("extern \"C\" JNIEXPORT ").append(Types.c(m.getReturnType())).append(" JNICALL ").append(jni).append("(JNIEnv* env, ");b.append((m.getAccessFlags()&0x8)!=0?"jclass clazz":"jobject thiz");int pi=0;for(String p:m.getParameterTypes())b.append(", ").append(Types.c(p)).append(" p").append(pi++);b.append(") {\n");
  b.append("  jthrowable pendingException = NULL;\n"); for(Value v:allVars(ir))if(v instanceof Variable){Variable x=(Variable)v;String t=Types.c(x.getType());b.append("  ").append(t).append(" ").append(var(x,ir)).append(defaultInit(x.getType())).append(";\n");}
  for(IrBasicBlock n:ir.irblocks){if(n.start<0)continue;b.append("\n").append(n.label()).append(":\n");for(Phi p:n.phis){}for(Instruction ii:n.instrList)b.append("  ").append(lower((DexInstruction)ii,ir,n)).append("\n");emitTerminator(b,n,ir);}
  for(LandingPad lp:ir.graph.landingPads){b.append("\n").append(lp.label()).append(":\n  pendingException = env->ExceptionOccurred(); env->ExceptionClear();\n");for(Map.Entry<String,IrBasicBlock> h:lp.handles.entrySet()){b.append("  if (pendingException && env->IsInstanceOf(env, pendingException, env->FindClass(\"").append(Types.descToClass(h.getKey())).append("\"))) goto ").append(h.getValue().label()).append(";\n");}b.append("  if(pendingException) env->Throw(pendingException); goto EX_UnwindBlock;\n");} if ("V".equals(m.getReturnType())) b.append("EX_Return: return;\nEX_UnwindBlock: return;\n"); else b.append("EX_Return: return ("+Types.c(m.getReturnType())+")0;\nEX_UnwindBlock: return ("+Types.c(m.getReturnType())+")0;\n"); b.append("}\n");if(dynamic)b.append(dynamicTable(m,jni));return b.toString();}
 private Collection<Value> allVars(IrMethod ir){Set<Value> s=Collections.newSetFromMap(new IdentityHashMap<>());for(IrBasicBlock n:ir.irblocks){s.addAll(n.varToDeclare);s.addAll(n.phis);for(Instruction i:n.instrList){if(i.getValue()!=null)s.add(i.getValue());s.addAll(i.getOperands());}}return s;}
 private String var(Variable v,IrMethod ir){return "v"+ir.ra.get(v);}
 private String defaultInit(String t){return Types.ref(t)?" = NULL": " = 0";}
 private String lower(DexInstruction d,IrMethod ir,IrBasicBlock block){String o=d.opcode();int[] r=d.registers();String dst=d.getValue() instanceof Variable?var((Variable)d.getValue(),ir):null;String a=r.length>0?value(r[0],d,ir):"0";String b=r.length>1?value(r[1],d,ir):"0";String c=r.length>2?value(r[2],d,ir):"0";
  if(o.equals("nop"))return ";";if(o.startsWith("move-result"))return dst+" = "+valueVar(d.getOperands().isEmpty()?null:d.getOperands().get(0),ir)+";";
  if(o.startsWith("move")&&!o.startsWith("move-result")&&!o.equals("move-exception"))return dst+" = "+b+";";
  if(o.equals("move-exception"))return dst+" = pendingException;";
  if(o.startsWith("const-string")){String sv=d.reference() instanceof com.android.tools.smali.dexlib2.iface.reference.StringReference?((com.android.tools.smali.dexlib2.iface.reference.StringReference)d.reference()).getString():String.valueOf(d.reference());return dst+" = env->NewStringUTF(\""+Types.escape(sv)+"\");";}
  if(o.equals("const-class")){String t=refType(d);return dst+" = env->FindClass(\""+Types.escape(Types.descToClass(t))+"\");";}
  if(o.startsWith("const")){String ct=d.getValue()==null?"I":d.getValue().getType();if("F".equals(ct))return dst+" = nt_f32((uint32_t)"+literal(d)+");";if("D".equals(ct))return dst+" = nt_f64((uint64_t)"+literal(d)+");";return dst+" = "+literal(d)+";";}
  if(o.equals("array-length"))return dst+" = env->GetArrayLength((jarray)"+b+");";
  if(o.equals("new-instance")){String t=refType(d);return dst+" = env->AllocObject(env->FindClass(\""+Types.escape(Types.descToClass(t))+"\"));"+checkException(block,ir);}
  if(o.equals("new-array")){String t=refType(d);return newArray(dst,b,t)+checkException(block,ir);}
  if(o.equals("filled-new-array")||o.equals("filled-new-array/range")){String t=refType(d);return filledArray(dst,r,t,d,ir);}
  if(o.equals("throw"))return "pendingException = (jthrowable)"+a+"; env->Throw(pendingException);";
  if(o.equals("monitor-enter"))return "env->MonitorEnter((jobject)"+a+");"+checkException(block,ir);
  if(o.equals("monitor-exit"))return "env->MonitorExit((jobject)"+a+");"+checkException(block,ir);
  if(o.equals("check-cast")){String t=refType(d);return "if("+a+" && !env->IsInstanceOf(env, (jobject)"+a+", env->FindClass(\""+Types.descToClass(t)+"\"))) { env->ThrowNew(env->FindClass(\"java/lang/ClassCastException\"), \"check-cast\"); goto EX_UnwindBlock; }";}
  if(o.equals("instance-of")){String t=refType(d);return dst+" = ("+a+" && env->IsInstanceOf(env, (jobject)"+a+", env->FindClass(\""+Types.descToClass(t)+"\")) ? 1 : 0);";}
  if(o.startsWith("aget"))return arrayGet(d,dst,b,c)+checkException(block,ir);
  if(o.startsWith("aput"))return arrayPut(d,a,b,c)+checkException(block,ir);
  if(o.equals("fill-array-data"))return "/* fill-array-data payload is lowered when payload metadata is available */";
  if(o.startsWith("iget"))return fieldGet(d,dst,b,false)+checkException(block,ir);
  if(o.startsWith("iput"))return fieldPut(d,a,b,false)+checkException(block,ir);
  if(o.startsWith("sget"))return fieldGet(d,dst,null,true)+checkException(block,ir);
  if(o.startsWith("sput"))return fieldPut(d,a,null,true)+checkException(block,ir);
  if(o.startsWith("invoke-"))return invoke(d,ir)+checkException(block,ir);
  if(o.startsWith("return"))return "/* return terminator */";
  if(o.startsWith("neg-"))return dst+" = -"+b+";";if(o.startsWith("not-"))return dst+" = ~"+b+";";
  String cast=castOp(o,b);if(cast!=null)return dst+" = "+cast+";";
  String bin=binOp(o);if(bin!=null){String rhs;if(o.contains("lit")){long lit=d.literal()==null?0:d.literal();if(o.startsWith("rsub"))rhs="("+lit+" - "+b+")";else rhs="("+b+" "+bin+" "+lit+")";}else if(o.contains("2addr"))rhs="("+a+" "+bin+" "+b+")";else rhs="("+b+" "+bin+" "+c+")";if(bin.equals("/")&&o.contains("int"))rhs="nt_div_i(env,"+b+","+c+")";if(bin.equals("%")&&o.contains("int"))rhs="nt_rem_i(env,"+b+","+c+")";if(bin.equals("/")&&o.contains("long"))rhs="nt_div_l(env,"+b+","+c+")";if(bin.equals("%")&&o.contains("long"))rhs="nt_rem_l(env,"+b+","+c+")";if(bin.equals("%")&&o.contains("float"))rhs="fmodf("+b+","+c+")";if(bin.equals("%")&&o.contains("double"))rhs="fmod("+b+","+c+")";if(o.startsWith("ushr"))rhs="((uint64_t)"+ (o.contains("long")?b:b)+" >> ("+(o.contains("long")?c:c)+" & "+(o.contains("long")?"63":"31")+"))";if(o.startsWith("shl")||o.startsWith("shr"))rhs="("+b+" "+bin+" ("+c+" & "+(o.contains("long")?"63":"31")+"))";return dst+" = "+rhs+";";}
  if(o.startsWith("cmp"))return dst+" = ("+b+" > "+c+" ? 1 : ("+b+" < "+c+" ? -1 : 0));";
  return "/* UNSUPPORTED: "+o+" */";
 }
 private String checkException(IrBasicBlock block,IrMethod ir){LandingPad lp=ir.graph.nodeToLandingPad.get(block);return lp==null?"":" if(env->ExceptionCheck()){ pendingException=env->ExceptionOccurred(); env->ExceptionClear(); goto "+lp.label()+"; }";}
 private String value(int reg,DexInstruction d,IrMethod ir){for(Value v:d.getOperands())if(v instanceof Variable && ((Variable)v).getRegister()==reg)return var((Variable)v,ir);return "v0";}
 private String valueVar(Value v,IrMethod ir){return v instanceof Variable?var((Variable)v,ir):v instanceof Constant?String.valueOf(((Constant)v).getConstant()):"0";}
 private String literal(DexInstruction d){if(d.literal()==null)return "0";if("const/high16".equals(d.opcode()))return Long.toString(d.literal());return Long.toString(d.literal());}
 private String refType(DexInstruction d){if(d.reference() instanceof TypeReference)return ((TypeReference)d.reference()).getType();return "Ljava/lang/Object;";}
 private String filledArray(String dst,int[] regs,String t,DexInstruction d,IrMethod ir){StringBuilder x=new StringBuilder();x.append(newArray(dst,Integer.toString(regs.length),t));String e=t==null?"Ljava/lang/Object;":t.substring(1);for(int i=0;i<regs.length;i++){String v=value(regs[i],d,ir);if(e.startsWith("L")||e.startsWith("["))x.append(" env->SetObjectArrayElement((jobjectArray)").append(dst).append(", ").append(i).append(", (jobject)").append(v).append(");");else x.append(" /* fill primitive */ ");}return x.toString();}
 private String newArray(String dst,String size,String t){if(t==null||!t.startsWith("["))return dst+" = NULL;";String e=t.substring(1);if("Z".equals(e))return dst+" = env->NewBooleanArray((jsize)"+size+");";if("B".equals(e))return dst+" = env->NewByteArray((jsize)"+size+");";if("C".equals(e))return dst+" = env->NewCharArray((jsize)"+size+");";if("S".equals(e))return dst+" = env->NewShortArray((jsize)"+size+");";if("I".equals(e))return dst+" = env->NewIntArray((jsize)"+size+");";if("J".equals(e))return dst+" = env->NewLongArray((jsize)"+size+");";if("F".equals(e))return dst+" = env->NewFloatArray((jsize)"+size+");";if("D".equals(e))return dst+" = env->NewDoubleArray((jsize)"+size+");";return dst+" = env->NewObjectArray((jsize)"+size+", env->FindClass(\""+Types.descToClass(e)+"\"), NULL);";}
 private String castOp(String o,String b){if(o.equals("int-to-long"))return "(jlong)"+b;if(o.equals("int-to-float"))return "(jfloat)"+b;if(o.equals("int-to-double"))return "(jdouble)"+b;if(o.equals("long-to-int"))return "(jint)"+b;if(o.equals("long-to-float"))return "(jfloat)"+b;if(o.equals("long-to-double"))return "(jdouble)"+b;if(o.equals("float-to-int"))return "(jint)"+b;if(o.equals("float-to-long"))return "(jlong)"+b;if(o.equals("float-to-double"))return "(jdouble)"+b;if(o.equals("double-to-int"))return "(jint)"+b;if(o.equals("double-to-long"))return "(jlong)"+b;if(o.equals("double-to-float"))return "(jfloat)"+b;if(o.equals("int-to-byte"))return "(jbyte)"+b;if(o.equals("int-to-char"))return "(jchar)"+b;if(o.equals("int-to-short"))return "(jshort)"+b;return null;}
 private String binOp(String o){if(o.contains("-add-"))return "+";if(o.contains("-sub-")||o.startsWith("rsub"))return "-";if(o.contains("-mul-"))return "*";if(o.contains("-div-"))return "/";if(o.contains("-rem-"))return "%";if(o.contains("-and-"))return "&";if(o.contains("-or-"))return "|";if(o.contains("-xor-"))return "^";if(o.contains("-shl-"))return "<<";if(o.contains("-shr-"))return ">>";if(o.contains("-ushr-"))return ">>";return null;}
 private String arrayGet(DexInstruction d,String dst,String arr,String idx){String s=d.opcode().contains("object")?"Object":d.opcode().contains("boolean")?"Boolean":d.opcode().contains("byte")?"Byte":d.opcode().contains("char")?"Char":d.opcode().contains("short")?"Short":d.opcode().contains("wide")?"Long":"Int";if("Object".equals(s))return dst+" = env->GetObjectArrayElement((jobjectArray)"+arr+", (jsize)"+idx+");";return "env->Get"+s+"ArrayRegion(("+arrayType(s)+")"+arr+", (jsize)"+idx+", 1, &"+dst+");";}
 private String arrayPut(DexInstruction d,String val,String arr,String idx){String s=d.opcode().contains("object")?"Object":d.opcode().contains("boolean")?"Boolean":d.opcode().contains("byte")?"Byte":d.opcode().contains("char")?"Char":d.opcode().contains("short")?"Short":d.opcode().contains("wide")?"Long":"Int";if("Object".equals(s))return "env->SetObjectArrayElement((jobjectArray)"+arr+", (jsize)"+idx+", (jobject)"+val+");";return "env->Set"+s+"ArrayRegion(("+arrayType(s)+")"+arr+", (jsize)"+idx+", 1, &"+val+");";}
 private String arrayType(String s){if("Boolean".equals(s))return "jbooleanArray";if("Byte".equals(s))return "jbyteArray";if("Char".equals(s))return "jcharArray";if("Short".equals(s))return "jshortArray";if("Long".equals(s))return "jlongArray";if("Float".equals(s))return "jfloatArray";if("Double".equals(s))return "jdoubleArray";return "jintArray";}
 private String fieldGet(DexInstruction d,String dst,String obj,boolean stat){if(!(d.reference() instanceof FieldReference))return "/* bad field */";FieldReference f=(FieldReference)d.reference();String cls=Types.descToClass(f.getDefiningClass()),name=Types.escape(f.getName()),sig=Types.escape(f.getType());String id="env->Get"+(stat?"Static":"")+"FieldID(env, env->FindClass(\""+cls+"\"), \""+name+"\", \""+sig+"\")";String suf=Types.jniSuffix(f.getType());return dst+" = env->Get"+(stat?"Static":"")+suf+"Field("+(stat?"env->FindClass(\""+cls+"\")":obj)+", "+id+");";}
 private String fieldPut(DexInstruction d,String val,String obj,boolean stat){if(!(d.reference() instanceof FieldReference))return "/* bad field */";FieldReference f=(FieldReference)d.reference();String cls=Types.descToClass(f.getDefiningClass()),name=Types.escape(f.getName()),sig=Types.escape(f.getType());String id="env->Get"+(stat?"Static":"")+"FieldID(env, env->FindClass(\""+cls+"\"), \""+name+"\", \""+sig+"\")";return "env->Set"+(stat?"Static":"")+Types.jniSuffix(f.getType())+"Field("+(stat?"env->FindClass(\""+cls+"\")":obj)+", "+id+", "+val+");";}
 private String invoke(DexInstruction d,IrMethod ir){if(!(d.reference() instanceof MethodReference))return "/* unsupported invoke ref */";MethodReference m=(MethodReference)d.reference();String cls=Types.descToClass(m.getDefiningClass()),sig=Types.escape(descriptor(m)),name=Types.escape(m.getName());boolean stat=d.opcode().contains("static");String call=stat?"CallStatic":"Call";String suf=Types.jniSuffix(m.getReturnType());String obj=stat?"env->FindClass(\""+cls+"\")":"(jobject)"+(d.registers().length>0?value(d.registers()[0],d,ir):"thiz");StringBuilder args=new StringBuilder();int start=stat?0:1;for(int i=start;i<d.registers().length;i++){if(args.length()>0)args.append(", ");args.append(value(d.registers()[i],d,ir));}String expr="env->Get"+(stat?"Static":"")+"MethodID(env, env->FindClass(\""+cls+"\"), \""+name+"\", \""+sig+"\")";String result=d.getValue() instanceof Variable?var((Variable)d.getValue(),ir):null;String callExpr=call+suf+"Method("+obj+", "+expr+(args.length()>0?", "+args:"")+")";return result==null?callExpr+";":result+" = "+callExpr+";";}
 private void emitTerminator(StringBuilder b,IrBasicBlock n,IrMethod ir){if(n.instrList.isEmpty()){List<IrBasicBlock> es=ir.graph.sucs(n);if(es.size()==1)edge(b,n,es.get(0),ir);return;}DexInstruction d=(DexInstruction)n.instrList.get(n.instrList.size()-1);String o=d.opcode();List<IrBasicBlock>s=ir.graph.sucs(n);if(o.startsWith("return")){String rv=d.getOperands().isEmpty()?"":valueVar(d.getOperands().get(0),ir);if("V".equals(ir.returnType))b.append("  return;\n");else b.append("  return ").append(rv.isEmpty()?"0":rv).append(";\n");return;}if(o.equals("throw")){b.append("  goto EX_UnwindBlock;\n");return;}if(o.startsWith("if-")&&s.size()>=2){String cond=condition(o,d,ir);IrBasicBlock taken=s.get(0),fall=s.get(1);b.append("  if (").append(cond).append(") { ");edge(b,n,taken,ir);b.append(" } else { ");edge(b,n,fall,ir);b.append(" }\n");return;}if(o.startsWith("goto")&&!s.isEmpty()){edge(b,n,s.get(0),ir);return;}if((o.equals("packed-switch")||o.equals("sparse-switch"))&&!s.isEmpty()){b.append("  switch((jint)").append(d.getOperands().isEmpty()?"0":valueVar(d.getOperands().get(0),ir)).append(") {\n");for(var e:d.switchTargets().entrySet()){for(IrBasicBlock x:s)if(x.start==e.getValue()){b.append("    case ").append(e.getKey()).append(": ");edge(b,n,x,ir);break;}}b.append("    default: ");for(IrBasicBlock x:s){boolean used=d.switchTargets().containsValue(x.start);if(!used){edge(b,n,x,ir);break;}}b.append("  }\n");return;}if(s.size()==1){edge(b,n,s.get(0),ir);}else if(s.size()>1){edge(b,n,s.get(0),ir);}else b.append("  goto EX_Return;\n");}
 private String condition(String o,DexInstruction d,IrMethod ir){String a=d.getOperands().size()>0?valueVar(d.getOperands().get(0),ir):"0",b=d.getOperands().size()>1?valueVar(d.getOperands().get(1),ir):"0";if(o.endsWith("eqz"))b="0";if("if-eq".equals(o)||"if-eqz".equals(o))return a+" == "+b;if("if-ne".equals(o)||"if-nez".equals(o))return a+" != "+b;if("if-lt".equals(o)||"if-ltz".equals(o))return a+" < "+b;if("if-ge".equals(o)||"if-gez".equals(o))return a+" >= "+b;if("if-gt".equals(o)||"if-gtz".equals(o))return a+" > "+b;if("if-le".equals(o)||"if-lez".equals(o))return a+" <= "+b;return "false";}
 private void edge(StringBuilder b,IrBasicBlock from,IrBasicBlock to,IrMethod ir){for(Phi p:to.phis){Value in=p.getOperands().get(from);if(in!=null)b.append("v").append(ir.ra.get(p)).append(" = ").append(valueVar(in,ir)).append("; ");}b.append("goto ").append(to.label()).append(";\n");}
 private String dynamicTable(Method m,String jni){return "\n/* RegisterNatives entry for "+m.getName()+descriptor(m)+" -> "+jni+" */\n";}
 private static String descriptor(MethodReference m){StringBuilder x=new StringBuilder("(");for(String p:m.getParameterTypes())x.append(p);return x.append(")").append(m.getReturnType()).toString();} private static String descriptor(Method m){StringBuilder x=new StringBuilder("(");for(String p:m.getParameterTypes())x.append(p);return x.append(")").append(m.getReturnType()).toString();}
 static final class JniNames{static String name(Method m){String c=m.getDefiningClass();c=c.substring(1,c.length()-1).replace('_','_').replace('/','_');String n=m.getName().replace("_","_1");return "Java_"+c+"_"+n;}}
}
